import{_ as t,o as a,c as s,a3 as r}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Home Assistant Card Editor","description":"Plugin de référence ATLAS : workflow Expert, commandes mobiles, connexion et points d’extension.","frontmatter":{"title":"Home Assistant Card Editor","description":"Plugin de référence ATLAS : workflow Expert, commandes mobiles, connexion et points d’extension."},"headers":[],"relativePath":"fr/projects/atlas-plugins/homeassistant-card-editor.md","filePath":"fr/projects/atlas-plugins/homeassistant-card-editor.md","lastUpdated":1792861021000}'),i={name:"fr/projects/atlas-plugins/homeassistant-card-editor.md"};function n(o,e,l,d,c,u){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="home-assistant-card-editor" tabindex="-1">Home Assistant Card Editor <a class="header-anchor" href="#home-assistant-card-editor" aria-label="Permalink to &quot;Home Assistant Card Editor&quot;">​</a></h1><p>Le Home Assistant Card Editor est le premier plugin officiel de référence ATLAS. Il illustre le cycle de vie, la découverte, l’Administration, le Hub, l’import/export et la création de packages. Son <a href="/fr/projects/atlas/card-editor">guide utilisateur</a> détaille les cartes et les styles.</p><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Au 16/10/2026 : plugin de référence <strong>0.2.0-alpha.108</strong> dans l’App <strong>0.1.312</strong>. Il est mis à jour avec ATLAS, pas comme un plugin externe à remplacer. Voir le <a href="./../atlas/card-editor">guide de l’éditeur</a> et les <a href="./../atlas/frontend">projets App/Runtime</a> pour projets partagés et parcours HACS.</p><p>Décision du 13/10/2026 : l’éditeur conserve uniquement le workflow Expert. Le mode Simple et son sélecteur ne seront pas réintroduits. Les imports de projets anciens pris en charge restent compatibles.</p><p>Depuis l’application HA <strong>0.1.292</strong>, le choix du mode de démarrage disparaît aussi de la configuration HA et de l’Administration. Les anciennes valeurs Simple sont traitées comme Expert ; identifiants et autres paramètres sont conservés.</p><p>Le plugin propose la sélection d’entités, les vérifications de ressources, l’import YAML/JSON, les bundles destinés à HACS et les packages multilingues. Les cellules de la grille restent carrées. Le curseur horizontal règle les colonnes et le curseur vertical les lignes ; Zoom modifie la taille des cellules et leurs deux dimensions ensemble.</p><h2 id="liste-des-cartes-sur-tablette" tabindex="-1">Liste des cartes sur tablette <a class="header-anchor" href="#liste-des-cartes-sur-tablette" aria-label="Permalink to &quot;Liste des cartes sur tablette&quot;">​</a></h2><p>Depuis l’application HA <strong>0.1.290</strong>, une largeur d’éditeur de 521 à 1180 pixels affiche deux cartes côte à côte dans une fenêtre défilante. Sa hauteur suit la première rangée et reste limitée sur les écrans peu hauts. Le défilement donne accès aux autres cartes. Les boutons au-dessus de la liste utilisent aussi deux colonnes de même largeur. Les téléphones étroits conservent une colonne ; la barre latérale de bureau reste inchangée. La largeur de l’éditeur intégré détermine la présentation, pas le nom de l’appareil. Les projets, favoris et paramètres existants sont conservés.</p><h2 id="commandes-mobiles-de-grille-et-de-titre" tabindex="-1">Commandes mobiles de grille et de titre <a class="header-anchor" href="#commandes-mobiles-de-grille-et-de-titre" aria-label="Permalink to &quot;Commandes mobiles de grille et de titre&quot;">​</a></h2><p>Depuis l’application HA <strong>0.1.291</strong>, Grille et zoom est replié par défaut jusqu’à une largeur d’éditeur de 1180 pixels. Touchez le titre pour afficher X, Y et Zoom ; ouvrir ou fermer le groupe ne modifie aucune valeur ou carte. À la largeur de bureau, les curseurs s’affichent directement.</p><p>Sur tablette, le champ de titre et les deux boutons d’application du titre et du nom d’entité partagent une rangée. Sur téléphone étroit, le champ se trouve au-dessus des deux boutons de même largeur. Cela s’applique en DE/EN/FR.</p><h2 id="connexion-avec-de-grands-catalogues-d-entites" tabindex="-1">Connexion avec de grands catalogues d’entités <a class="header-anchor" href="#connexion-avec-de-grands-catalogues-d-entites" aria-label="Permalink to &quot;Connexion avec de grands catalogues d’entités&quot;">​</a></h2><p>Depuis l’application HA <strong>0.1.293</strong>, ATLAS traite les instantanés d’entités et événements en direct dans leur ordre d’arrivée. Un instantané en cours ne peut plus terminer après un événement reçu ensuite et remplacer sa valeur par une ancienne. Les messages d’une connexion fermée sont ignorés ; l’échec d’un nouveau socket affiche son propre état. Les cartes, positions et identifiants enregistrés restent inchangés.</p><h2 id="points-d-extension" tabindex="-1">Points d’extension <a class="header-anchor" href="#points-d-extension" aria-label="Permalink to &quot;Points d’extension&quot;">​</a></h2><p>Le plugin utilise :</p><ul><li><code>homeassistant.card-editor</code></li><li><code>homeassistant.card-target</code></li><li><code>homeassistant.entity-picker</code></li><li><code>homeassistant.exporter</code></li><li><code>atlas.plugin.package-builder</code></li></ul><h2 id="package" tabindex="-1">Package <a class="header-anchor" href="#package" aria-label="Permalink to &quot;Package&quot;">​</a></h2><p><code>createHomeAssistantCardEditorPluginInstallPackage()</code> crée le package d’installation avec son manifeste, un README et un exemple de configuration HA.</p><h2 id="description-dans-le-hub" tabindex="-1">Description dans le Hub <a class="header-anchor" href="#description-dans-le-hub" aria-label="Permalink to &quot;Description dans le Hub&quot;">​</a></h2><p>Le Hub et l’Administration utilisent les descriptions localisées du dépôt. La langue sélectionnée donne la priorité à <code>descriptions.de</code>, <code>descriptions.en</code> ou <code>descriptions.fr</code> lorsqu’elles sont disponibles ; l’anglais reste la langue de repli.</p>',21)])])}const g=t(i,[["render",n]]);export{m as __pageData,g as default};
